    "summary": "Retry money-moving requests safely with an Idempotency-Key header.",
    "text": "export default function Idempotency() {\n return (\n <>\n \n Network failures happen. Retrying a request without safeguards can double-charge a customer or send a\n charge twice. The Idempotency-Key header lets you retry safely.\n\n How it works \n \n Send a unique Idempotency-Key header (max 255 chars — a UUID is ideal) with any money-moving\n request. We store the response for 24 hours keyed by (business, endpoint, key) .\n Retries with the same key return the original response with an Idempotent-Replayed: true header.\n\n POST /v1/collect/momo . Hosted checkout sessions and read\n endpoints don't need it (reads are already idempotent).\n\n Example \n HTTP/2 201\n# -> idempotent-replayed: true\n# -> body is identical to the first response ,\n },\n {\n label: 'JavaScript',\n lang: 'js',\n filename: 'retry.js',\n code: // One key per business event — reused across every retry.\nconst idempotencyKey = \"8f4b7c1e-invoice-a104\"\n\nasync function charge(attempt = 1) {\n const res = await fetch(\"$ /$ /collect/momo\", {\n method: \"POST\",\n headers: ,\n body: JSON.stringify( ),\n })\n if (res.status >= 500 && attempt true,\n CURLOPT_RETURNTRANSFER => true,\n CURLOPT_HTTPHEADER => [\n \"Authorization: Bearer wr_test_...\",\n \"Content-Type: application/json\",\n \"Idempotency-Key: \" . $idempotencyKey,\n ],\n CURLOPT_POSTFIELDS => json_encode([\n \"amount\" => 10.50,\n \"subscriber_number\" => \"0240000000\",\n \"network\" => \"MTN\",\n ]),\n ]);\n $body = curl_exec($ch);\n $status = curl_getinfo($ch, CURLINFO_HTTP_CODE);\n if ($status >= 500 && $attempt \n\n Conflicts \n\n Recovering a lost transaction id \n \n If the response to a POST is lost in transit you can look the transaction up by the\n Idempotency-Key you sent, without re-issuing the money-moving request:\n \n { \"items\": [ ], ... }\n# -> Empty items[] means we have no record — safe to retry the POST with the same key. ,\n },\n {\n label: 'JavaScript',\n lang: 'js',\n filename: 'recover.js',\n code: const key = \"8f4b7c1e-invoice-a104\"\nconst page = await fetch(\n \\ $ /$ /transactions?idempotency_key=\\$ \\ ,\n { headers: },\n).then((r) => r.json())\n\nconst existing = page.items[0]\nif (!existing) ,\n },\n {\n label: 'PHP',\n lang: 'php',\n filename: 'recover.php',\n code: $key = \"8f4b7c1e-invoice-a104\";\n$url = \"$ /$ /transactions?\" . http_build_query([\"idempotency_key\" => $key]);\n$ch = curl_init($url);\ncurl_setopt_array($ch, [\n CURLOPT_RETURNTRANSFER => true,\n CURLOPT_HTTPHEADER => [\"Authorization: Bearer wr_live_...\"],\n]);\n$page = json_decode(curl_exec($ch), true);\n$existing = $page[\"items\"][0] ?? null; // null => safe to retry the POST ,\n },\n ]}\n />\n\n Best practices \n \n Generate a UUID per business event (invoice id, order id) and reuse it across retries. \n Set client-side timeouts to at least 30s — MoMo prompts can be slow. \n Retry on network errors and 5xx . Do not retry on 4xx other than 429 . \n On a lost response, look up by idempotency_key before assuming failure. \n\n )\n}"
